mapper.select:
SELECT et.theme_id as id, et.theme_name as `name` , COUNT(et.id) as total_num FROM safety_exam_task et left join market_config mc on mc.market_tenant = et.market_tenant
mc.status = true and mc.deleted = 0
and et.market_tenant = #{query.marketTenant}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
GROUP BY theme_id

SELECT
COUNT(DISTINCT et.id) as total_num
FROM
safety_exam_task et
left join market_config mc on mc.market_tenant = et.market_tenant

    mc.status = true and mc.deleted = 0

        and et.market_tenant = #{query.marketTenant}


        and et.market_tenant in

            #{marketTenantId}



        and et.exam_start_time >= #{query.period.begin}


        and et.exam_start_time <= #{query.period.end}

SELECT mc.market_tenant, COALESCE ( sub.total_num, 0 ) AS total_num, mc.market_name FROM market_config mc LEFT JOIN ( SELECT market_tenant, COUNT( 1 ) AS total_num FROM safety_exam_task
and market_tenant = #{query.marketTenant}
and market_tenant in
#{marketTenantId}
and exam_start_time >= #{query.period.begin}
and exam_start_time <= #{query.period.end}
GROUP BY market_tenant ) sub ON mc.market_tenant = sub.market_tenant WHERE mc.`status` = TRUE AND mc.deleted = 0 ORDER BY sub.total_num DESC

SELECT distinct et.id, et.name, et.theme_id, et.theme_name, et.exam_start_time, et.exam_end_time, et.exam_paper_id, et.exam_paper_name, et.exam_paper_content, et.charge_user_id, et.charge_user_name, et.timed, et.exam_duration, et.exam_duration_unit, et.retake, et.retake_number, et.exam_task_type, et.exam_task_type_name, et.exam_user_number, et.exam_task_status, et.exam_task_status_name, et.published_time, et.remark, et.market_tenant, mc.market_name FROM safety_exam_task et left join market_config mc on mc.market_tenant = et.market_tenant
mc.status = true and mc.deleted = 0
and ( et.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_status = #{query.status}
and et.exam_task_type = #{query.examType}
and et.market_tenant = #{query.marketTenant}
and et.market_tenant in
#{marketTenantId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
order by et.create_time desc
